+// Sales from the till. Each dish sold uses one portion of its recipe per
+// `qty`; the ingredients are consumed with the ledger ref `sale:<ticket>`.
+// A ticket is imported once, and an import is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/**
+ * Imports till rows ({ row, ticket, soldAt, dishId, qty }): skips tickets
+ * imported before, checks every row and the stock first, then consumes the
+ * ingredients at `soldAt` and keeps the sales. Returns { tickets, dishes }.
+ */
+export function importSales(store, rows, { at }) {
+  const known = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const left = new Map();
+  const lines = [];
+  for (const r of rows) {
+    const dish = (store.data.dishes ?? []).find((d) => d.id === r.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${r.row}: unknown dish ${r.dishId}` });
+    if (known.has(r.ticket)) continue;
+    const use = scaled(getRecipe(store, dish.recipeId), r.qty).filter((u) => u.qty > 0);
+    for (const u of use) {
+      const item = getItem(store, u.itemId);
+      const available = left.get(u.itemId) ?? round3(onHand(store, u.itemId));
+      if (available < u.qty)
+        throw new AppError("sale_not_enough_stock", { row: r.row, item: item.name, available, unit: item.unit });
+      left.set(u.itemId, round3(available - u.qty));
+    }
+    lines.push({ ...r, use });
+  }
+  store.data.sales ??= [];
+  for (const l of lines) {
+    for (const u of l.use) consume(store, u.itemId, u.qty, { at: l.soldAt, ref: `sale:${l.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: l.ticket, soldAt: l.soldAt, dishId: l.dishId, qty: l.qty, use: l.use, importedAt: at });
+  }
+  return { tickets: new Set(lines.map((l) => l.ticket)).size, dishes: lines.reduce((s, l) => s + l.qty, 0) };
+}
