diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..7ed9622
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,37 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty). The whole file
+// is checked first; one bad row and nothing is imported. Rows are named by
+// their line in the file: row 1 is the header, row 2 the first data row.
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { importSales } from "../domain/sales.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const INSTANT = /^(\d{4}-\d{2}-\d{2})T([01]\d|2[0-3]):[0-5]\d(:[0-5]\d(\.\d+)?)?(Z|[+-]([01]\d|2[0-3]):[0-5]\d)$/;
+
+// An ISO 8601 instant as a UTC ISO string, or null.
+function instant(text) {
+  const m = INSTANT.exec(text);
+  if (!m || !isDate(m[1])) return null;
+  const ms = Date.parse(text);
+  return Number.isNaN(ms) ? null : new Date(ms).toISOString();
+}
+
+/** Imports sales from CSV text at instant `at`; returns { tickets, dishes } or throws naming the row. */
+export function importSalesCsv(store, text, { at }) {
+  const lineNumbers = [];
+  String(text).split(/\r?\n/).forEach((line, i) => {
+    if (line.trim()) lineNumbers.push(i + 1);
+  });
+  const rows = parseCsvObjects(text).map((r, i) => {
+    const where = `row ${lineNumbers[i + 1]}`;
+    for (const k of HEADER) if (!(k in r)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+    const soldAt = instant(r.soldAt);
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!soldAt) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    if (!/^[1-9]\d{0,8}$/.test(r.dishId)) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    if (!/^[1-9]\d{0,5}$/.test(r.qty)) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { row: lineNumbers[i + 1], ticket: r.ticket, soldAt, dishId: Number(r.dishId), qty: Number(r.qty) };
+  });
+  return importSales(store, rows, { at });
+}
